const html = $input.first().json.html || "";
const email = $node["HTTP Request1"].json["lastModifiedBy"]?.user?.email?.toLowerCase() || "";

const emailClassMap = {
  "viktoria.andonova@exposeprofi.de": "viktoria",
  "vivien.sariewa@exposeprofi.de": "vivien",
  "sonia.kaniss@exposeprofi.de": "sonia",
  "projektmanagement@exposeprofi.de": "projektmanagement team",
  "a.maiger@exposeprofi.de":"projektmanagement team",
};

const className = emailClassMap[email];

let signatureDiv = "<div></div>";

if (className) {
  const regex = new RegExp(`<div class=['"]${className}['"][\\s\\S]*?<\\/div>`);

  const match = html.match(regex);
  if (match) {
    signatureDiv = match[0];
  }
}

// Properly escape json
const escapedSignature = JSON.stringify(signatureDiv).slice(1, -1);

return [{ json: { htmlSignature: escapedSignature } }];

// Parse input JSON
const input = items[0].json;

// Extract values array
const values = input.value || [];

// Allowed MIME types
const allowedMimeTypes = [
  "image/jpeg",
  "image/png",
  "application/pdf"
];

// Filter files by allowed MIME types
const filtered = values.filter(v =>
  v.file && allowedMimeTypes.includes(v.file.mimeType)
);

// Return results as individual items (Loop Over Items compatible)
return filtered.map(v => ({ json: v }));

const responseString = $input.first().json.data;

if (responseString === undefined) {

  console.error("Error: Input responseString is undefined. Check the output of the previous node.");

  return [{ json: { error: "Input responseString is undefined" } }];
}

const parsedResponse = JSON.parse(responseString);


const folderData = parsedResponse.data;

if (folderData === undefined) {
  console.error("Error: parsedResponse.data is undefined. Check the structure of the API response.");

  return [{ json: { error: "parsedResponse.data is undefined" } }];
}

const folderId = folderData.id;

if (folderId === undefined) {
  console.error("Error: folderData.id is undefined. Check the structure of the API response's inner data object.");

  return [{ json: { error: "folderData.id is undefined" } }];
}

return [{
  json: {
    newFolderId: folderId
  }
}];

const responseString = $input.first().json.data;

if (!responseString) {
  console.error("Error: Input responseString is undefined. Check the output of the previous node.");
  return [{ json: { error: "Input responseString is undefined" } }];
}

let parsedResponse;
try {
  parsedResponse = JSON.parse(responseString);
} catch (e) {
  console.error("Error parsing JSON:", e);
  return [{ json: { error: "Invalid JSON format in responseString" } }];
}

const link = parsedResponse?.data?.attributes?.link;

if (!link) {
  console.error("Error: 'link' field is missing in the response.");
  return [{ json: { error: "'link' field is missing" } }];
}

return [{
  json: {
    link
  }
}];

// n8n Code node — Mode: "Run Once for All Items"
// Creates the project on the revision tool by sending SharePoint download URLs
// (@microsoft.graph.downloadUrl) as JSON — the revision server downloads the
// files itself, so no image bytes ever pass through n8n on this branch.
const API_URL = 'https://revision.exposeprofi.de/api/v1/projects';
const API_KEY = $env.REVISION_API_KEY; // requires N8N_BLOCK_ENV_ACCESS_IN_NODE=false

if (!API_KEY) throw new Error('REVISION_API_KEY is not set in the n8n environment.');

// Only types the revision API accepts — PDFs stay on the Zoho branch
const IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];

// Project name + comment (one project for the whole batch)
let markupName = 'Untitled project';
let comment = '';
try {
  const derived = $('Derive Markup name1').first().json;
  markupName = derived.markupName || markupName;
  comment = derived.projectId ?? '';
} catch (e) { /* keep defaults */ }

const images = $input.all()
  .map(item => item.json)
  .filter(f => f['@microsoft.graph.downloadUrl'] && IMAGE_TYPES.includes(f.file?.mimeType))
  .map(f => ({
    url: f['@microsoft.graph.downloadUrl'],
    name: f.name,
  }));

if (images.length === 0) throw new Error('No downloadable images found in the folder items (expected @microsoft.graph.downloadUrl on jpeg/png/webp/gif files).');
if (images.length > 50) throw new Error(`Too many images (${images.length}) — the API accepts at most 50 per call.`);

const raw = await this.helpers.httpRequest({
  method: 'POST',
  url: API_URL,
  headers: {
    Authorization: `Bearer ${API_KEY}`,
    'Content-Type': 'application/json',
  },
  body: {
    name: markupName,
    comment,
    images,
    share: { permissions: 'comment' },
  },
  json: true,
  timeout: 120000,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
});

const status = raw.statusCode;
let response = raw.body;
if (typeof response === 'string') {
  try { response = JSON.parse(response); } catch { response = { raw: response }; }
}

// Surface the API's own error details (incl. per-image failures) instead of a
// generic HTTP error, so failed runs are diagnosable from the n8n execution log.
if (status < 200 || status >= 300) {
  throw new Error(`Revision API returned HTTP ${status} for ${images.length} image(s): ${JSON.stringify(response)}`);
}
if (response.failedImages?.length) {
  const summary = response.failedImages.map(f => `${f.input}: ${f.error}`).join(' | ');
  if (!response.images?.length) {
    throw new Error(`All ${response.failedImages.length} images failed to ingest — ${summary}`);
  }
  console.warn(`${response.failedImages.length} image(s) failed to ingest: ${summary}`);
}

// Downstream: {{ $('Create render on revision tool').first().json.project.url }}
return [{ json: response }];
